changeSet.sql:
CREATE TABLE ${ARENA_DB_SCHEMA}.club_public_site (
 academy_id BIGINT PRIMARY KEY REFERENCES ${ARENA_DB_SCHEMA}.customer(id),version BIGINT NOT NULL DEFAULT 0,
 slug VARCHAR(40) NOT NULL UNIQUE,published BOOLEAN NOT NULL DEFAULT FALSE,slug_changed_at TIMESTAMPTZ,
 bookings_enabled BOOLEAN NOT NULL DEFAULT FALSE,opens_at TIME,closes_at TIME,duration_minutes VARCHAR(100)
);
CREATE TABLE ${ARENA_DB_SCHEMA}.club_public_slug (slug VARCHAR(40) PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.club_public_site(academy_id));
CREATE INDEX club_slug_tenant ON ${ARENA_DB_SCHEMA}.club_public_slug(academy_id);
CREATE TABLE ${ARENA_DB_SCHEMA}.facility_permanent_qr (
 facility_id BIGINT PRIMARY KEY,academy_id BIGINT NOT NULL,public_id VARCHAR(43) NOT NULL UNIQUE,
 revoked BOOLEAN NOT NULL DEFAULT FALSE,suspended_until TIMESTAMPTZ,quota_reset_at TIMESTAMPTZ,
 FOREIGN KEY(facility_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_play_area(id,academy_id)
);
ALTER TABLE ${ARENA_DB_SCHEMA}.facility_qr_challenge ADD COLUMN created_at TIMESTAMPTZ,ADD COLUMN permanent_qr_id BIGINT REFERENCES ${ARENA_DB_SCHEMA}.facility_permanent_qr(facility_id);
CREATE TABLE ${ARENA_DB_SCHEMA}.club_customer (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.customer(id),
 identity_key VARCHAR(64) NOT NULL,name VARCHAR(100),mobile VARCHAR(16),verification VARCHAR(16) NOT NULL CHECK(verification='UNVERIFIED'),
 created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,deleted_at TIMESTAMPTZ,
 UNIQUE(academy_id,identity_key),UNIQUE(id,academy_id)
);
CREATE TABLE ${ARENA_DB_SCHEMA}.club_customer_visit (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,academy_id BIGINT NOT NULL,customer_id BIGINT NOT NULL,session_id BIGINT NOT NULL UNIQUE,started_at TIMESTAMPTZ NOT NULL,
 FOREIGN KEY(customer_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.club_customer(id,academy_id),
 FOREIGN KEY(session_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id)
);
CREATE INDEX club_visit_customer ON ${ARENA_DB_SCHEMA}.club_customer_visit(academy_id,customer_id,started_at);
ALTER TABLE ${ARENA_DB_SCHEMA}.facility_customer_checkin ADD COLUMN customer_id BIGINT,ADD COLUMN request_id UUID,ADD COLUMN request_hash VARCHAR(64),ADD COLUMN mobile_hash VARCHAR(64),
 ADD FOREIGN KEY(customer_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.club_customer(id,academy_id);
-- Retire previous short-lived pending requests; printed permanent IDs are issued explicitly after publishing.
UPDATE ${ARENA_DB_SCHEMA}.facility_customer_checkin SET status='EXPIRED',customer_name=NULL,mobile=NULL WHERE status='PENDING';
ALTER TABLE ${ARENA_DB_SCHEMA}.facility_customer_checkin DROP CONSTRAINT facility_customer_checkin_status_check;
ALTER TABLE ${ARENA_DB_SCHEMA}.facility_customer_checkin ADD CONSTRAINT facility_checkin_status_v2 CHECK(status IN ('PENDING','CONFIRMED','CANCELLED','REJECTED','EXPIRED'));
CREATE UNIQUE INDEX facility_one_pending_checkin ON ${ARENA_DB_SCHEMA}.facility_customer_checkin(academy_id,facility_id) WHERE status='PENDING';
CREATE UNIQUE INDEX facility_checkin_idempotency ON ${ARENA_DB_SCHEMA}.facility_customer_checkin(academy_id,facility_id,request_id) WHERE request_id IS NOT NULL;
CREATE INDEX facility_checkin_mobile_window ON ${ARENA_DB_SCHEMA}.facility_customer_checkin(academy_id,facility_id,mobile_hash,created_at);
CREATE TABLE ${ARENA_DB_SCHEMA}.facility_mobile_limit (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,facility_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.facility_permanent_qr(facility_id),mobile_hash VARCHAR(64) NOT NULL,blocked_until TIMESTAMPTZ NOT NULL,UNIQUE(facility_id,mobile_hash)
);
CREATE TABLE ${ARENA_DB_SCHEMA}.club_reservation_request (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,academy_id BIGINT NOT NULL,facility_id BIGINT NOT NULL,request_id UUID NOT NULL,request_hash VARCHAR(64) NOT NULL,
 reference VARCHAR(43) NOT NULL UNIQUE,customer_name VARCHAR(100),mobile VARCHAR(16),mobile_hash VARCHAR(64) NOT NULL,
 status VARCHAR(16) NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED','EXPIRED')),reserved_start TIMESTAMP NOT NULL,reserved_end TIMESTAMP NOT NULL CHECK(reserved_end>reserved_start),
 created_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,decided_at TIMESTAMPTZ,decided_by VARCHAR(100),session_id BIGINT,customer_id BIGINT,
 FOREIGN KEY(facility_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_play_area(id,academy_id),
 FOREIGN KEY(session_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id),
 FOREIGN KEY(customer_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.club_customer(id,academy_id),UNIQUE(academy_id,request_id),UNIQUE(session_id)
);
CREATE INDEX club_booking_pending ON ${ARENA_DB_SCHEMA}.club_reservation_request(academy_id,status,expires_at);
CREATE INDEX club_booking_mobile_window ON ${ARENA_DB_SCHEMA}.club_reservation_request(academy_id,mobile_hash,created_at);
